#!/usr/bin/env node
// Minifies the booking pages' scripts with esbuild into src/booking/pages/scripts.gen.js.
//
//   node Service/tools/build-book-scripts.mjs
//
// Run it after changing pages/kit.js or pages/client.js; test/booking-pages.test.js fails while the
// generated file is older than its sources. esbuild is the one wrangler bundles with, so nothing new
// is installed: it is found in node_modules, then beside the wrangler on the PATH (ESBUILD_PATH
// names another).

import { createHash } from "node:crypto";
import { createRequire } from "node:module";
import { existsSync, realpathSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { sources } from "../src/booking/pages/sources.js";

const HERE = dirname(fileURLToPath(import.meta.url));
const OUT = resolve(HERE, "../src/booking/pages/scripts.gen.js");

function findEsbuild() {
  const tries = [process.env.ESBUILD_PATH, join(HERE, "..", "node_modules", "esbuild")];
  try {
    const bin = execFileSync("sh", ["-c", "command -v wrangler"], { encoding: "utf8" }).trim();
    let dir = dirname(realpathSync(bin));
    if (dir.includes("volta")) dir = join(process.env.HOME, ".volta/tools/image/packages/wrangler/lib/node_modules/wrangler");
    for (let d = dir, i = 0; i < 4; i++, d = dirname(d)) tries.push(join(d, "node_modules", "esbuild"), join(d, "lib/node_modules/wrangler/node_modules/esbuild"));
  } catch { /* no wrangler on the PATH */ }
  for (const t of tries.filter(Boolean)) if (existsSync(join(t, "package.json"))) return createRequire(join(t, "package.json"))(t);
  throw new Error("esbuild not found: install wrangler, or set ESBUILD_PATH to an esbuild package folder");
}

/** The hash the tests compare: the sources as this Node prints them. */
export const hashOf = (src) => createHash("sha256").update(JSON.stringify(src)).digest("hex");

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const esbuild = findEsbuild();
  const src = sources(), out = {};
  for (const [name, code] of Object.entries(src)) {
    out[name] = esbuild.transformSync(code, { minify: true, target: "es2020", legalComments: "none", charset: "ascii" }).code.trim().replace(/;$/, "");
  }
  const { HEAD, KIT, ...pages } = out;
  writeFileSync(OUT, `// Generated by tools/build-book-scripts.mjs (esbuild ${esbuild.version}) from pages/kit.js and pages/client.js.
// Don't edit: change those and run the tool again.

export const SOURCE = ${JSON.stringify(hashOf(src))};
export const HEAD = ${JSON.stringify(HEAD)};
export const SCRIPTS = ${JSON.stringify(pages, null, 2)};
export const KIT = ${JSON.stringify(KIT)};
`);
  const { gzipSync } = await import("node:zlib");
  for (const [name, code] of Object.entries(pages)) console.log(`${name.padEnd(10)} ${code.length} bytes, ${gzipSync(code, { level: 9 }).length} gzipped`);
  console.log(`wrote ${OUT}`);
}
